import React, { Component } from 'react';
import './googlemap.css';

class Map extends Component {
    state = {
        userLocation: null,
        petLocation: null,
        historyRange: '',
        errorMessage: ''
    };

    componentDidMount() {
        this.initMap();
        this.startLocationUpdate();
    }

    componentWillUnmount() {
        const script = document.getElementById('googleMaps');
        if (script) {
            document.head.removeChild(script);
        }
        clearInterval(this.locationUpdateInterval);
    }

    initMap = () => {
        const loadScript = () => {
            const existingScript = document.getElementById('googleMaps');
            if (!existingScript) {
                const script = document.createElement('script');
                script.src = 'https://maps.googleapis.com/maps/api/js?key=AIzaSyB5t8KXIpcdx0n3I7FtsVtCJ86YoDngaYw&callback=initMap';
                script.id = 'googleMaps';
                script.async = true;
                script.defer = true;
                script.onload = this.initializeMap;
                document.head.appendChild(script);
            } else {
                this.initializeMap();
            }
        };
        loadScript();
    };

    initializeMap = () => {
        if (window.google && window.google.maps) {
            this.map = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 15,
                center: { lat: 32.074572, lng: 34.797105 } // מרכז ברירת מחדל
            });
        } else {
            console.error("Google Maps API failed to load.");
        }
    };

    startLocationUpdate = () => {
        this.locationUpdateInterval = setInterval(this.updatePetLocation, 60000); // עדכון כל דקה
        this.updatePetLocation(); // עדכון מיידי בהתחלה
    };

    updatePetLocation = () => {
        const pet_id = 1; // יש להחליף את ה-pet_id בהתאם

        fetch(`http://localhost:3001/locations?pet_id=${pet_id}`)
            .then(response => response.json())
            .then(data => {
                if (data.length > 0) {
                    const lastLocation = {
                        lat: parseFloat(data[0].latitude),
                        lng: parseFloat(data[0].longitude),
                    };

                    this.setState({ petLocation: lastLocation });

                    if (this.petMarker) {
                        this.petMarker.setPosition(lastLocation);
                    } else {
                        this.petMarker = new window.google.maps.Marker({
                            position: lastLocation,
                            map: this.map,
                            title: 'Pet Location'
                        });
                        this.map.setCenter(lastLocation);
                    }

                    this.updateUserLocation(lastLocation);
                }
            })
            .catch(error => console.error('Error fetching location points:', error));
    };

    updateUserLocation = (petLocation) => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(position => {
                const userLocation = {
                    lat: position.coords.latitude,
                    lng: position.coords.longitude
                };

                this.setState({ userLocation });

                if (this.userMarker) {
                    this.userMarker.setPosition(userLocation);
                } else {
                    this.userMarker = new window.google.maps.Marker({
                        position: userLocation,
                        map: this.map,
                        title: 'Your Location',
                        icon: {
                            url: 'http://maps.google.com/mapfiles/ms/icons/blue-dot.png'
                        }
                    });
                }

                this.drawRoute(userLocation, petLocation);
            });
        }
    };

    drawRoute = (userLocation, petLocation) => {
        const directionsService = new window.google.maps.DirectionsService();
        const directionsRenderer = new window.google.maps.DirectionsRenderer();
        directionsRenderer.setMap(this.map);

        const request = {
            origin: userLocation,
            destination: petLocation,
            travelMode: 'DRIVING'
        };

        directionsService.route(request, (result, status) => {
            if (status === 'OK') {
                directionsRenderer.setDirections(result);
            }
        });
    };

    handleHistoryRangeChange = (event) => {
        this.setState({ historyRange: event.target.value });
    };

    viewHistory = () => {
        const { historyRange } = this.state;
        if (!historyRange) {
            this.setState({ errorMessage: 'Please select a time range.' });
            return;
        }
        this.setState({ errorMessage: '' });

        const pet_id = 1; // יש להחליף את ה-pet_id בהתאם
        let timeRange = '';

        switch (historyRange) {
            case '1h':
                timeRange = 'hour';
                break;
            case '2h':
                timeRange = '2 hours';
                break;
            case '23h':
                timeRange = '23 hours';
                break;
            case '1d':
                timeRange = 'day';
                break;
            case '1w':
                timeRange = 'week';
                break;
            default:
                break;
        }

        fetch(`http://localhost:3001/locations/history?pet_id=${pet_id}&range=${timeRange}`)
            .then(response => response.json())
            .then(data => {
                const points = data.map(point => ({
                    lat: parseFloat(point.latitude),
                    lng: parseFloat(point.longitude),
                }));

                const bounds = new window.google.maps.LatLngBounds();
                points.forEach(point => bounds.extend(point));
                this.map.fitBounds(bounds);

                if (this.historyPath) {
                    this.historyPath.setMap(null);
                }

                this.historyPath = new window.google.maps.Polyline({
                    path: points,
                    geodesic: true,
                    strokeColor: '#FF0000',
                    strokeOpacity: 1.0,
                    strokeWeight: 2,
                });

                this.historyPath.setMap(this.map);
            })
            .catch(error => console.error('Error fetching location history:', error));
    };

    openGoogleMaps = () => {
        const { userLocation, petLocation } = this.state;
        if (userLocation && petLocation) {
            const url = `https://www.google.com/maps/dir/?api=1&origin=${userLocation.lat},${userLocation.lng}&destination=${petLocation.lat},${petLocation.lng}&travelmode=driving`;
            window.open(url, '_blank');
        }
    };

    render() {
        const { historyRange, errorMessage } = this.state;

        return (
            <div className="app-container">
                <div className="content-container-2">
                    <div className="sidebar">
                        <img src="../media/dog-location.png" alt="Dog Location" className="photo" />
                        <div className="dog-info">
                            <p className="info-text">Name: Bella</p>
                            <p className="info-text">Location: Tel Aviv</p>
                            <p className="info-text">Longitude: 32.074572</p>
                            <p className="info-text">Latitude: 34.797105</p>
                            <div className="history-controls">
                                <select value={historyRange} onChange={this.handleHistoryRangeChange}>
                                    <option value="">בחר תקופה</option>
                                    <option value="1h">לפני שעה</option>
                                    <option value="2h">לפני שעתיים</option>
                                    <option value="23h">לפני 23 שעות</option>
                                    <option value="1d">לפני יום</option>
                                    <option value="1w">לפני שבוע</option>
                                </select>
                                <button onClick={this.viewHistory} className="history-button">צפה בהיסטוריה</button>
                                {errorMessage && <p className="error-message">{errorMessage}</p>}
                            </div>
                            <button onClick={this.openGoogleMaps} className="navigate-button">
                                Navigate with Google Maps
                            </button>
                        </div>
                    </div>
                    <div id="map"></div>
                </div>
            </div>
        );
    }
}

export default Map;
